8	import { personalBand } from "@/lib/generator/rules";
9	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
10	import { rankTopN } from "@/lib/generator/rank";
11	import { currentSeason } from "@/lib/generator/season";
12	import { rerank } from "@/lib/generator/rerank";
13	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
14	import { localDateFor } from "@/lib/outfits/local-date";
15	import { assertCanGenerate, noteGeneration, QuotaExceededError } from "@/lib/outfits/quota";
16	import { predictOccasion } from "@/lib/outfits/predict-occasion";
17	import { pinItem, styledLookName, shortlistFor, STYLED_LOOKS } from "@/lib/outfits/styled";
18	import {
19	  loadStyledLooks,
20	  saveStyledLooks,
21	  clearStyledLooks,
22	  loadStyledPieceIds,
23	} from "@/lib/outfits/styled-store";
24	import { resolveLocation } from "@/lib/weather/location";
25	import type { LookDraft, LookPiece, WeatherPayload } from "@/lib/generator/types";
26	
27	export type StyleResult =
28	  | { status: "ok"; outfitIds: string[] }
29	  // Carries the seam's own reason. Styling is a Pro capability rather than a
30	  // daily allowance, so a message written here ("back tomorrow") would be
31	  // actively false — tomorrow gives a free user no stylings either.
32	  | { status: "limited"; message: string }
33	  | { status: "empty"; message: string }
34	  | { status: "error"; message: string };
35	
36	/**
37	 * "Style an outfit with this" (Fitcheck.dc.html:654).
38	 *
39	 * Pins the piece, runs the deterministic pipeline, spends ONE text call to name
40	 * and explain the result, then persists it keyed by (user, item, local day) so a
41	 * second tap the same day is a free read.
42	 *
43	 * This does not contradict Decision 5. That decision says never pay twice for a
44	 * question already answered — which is why the daily drop caches. "What goes
45	 * with this piece?" is a different question from "what should I wear today?",
46	 * so it gets its own answer, cached the same way.
