1	import { weatherRules, type Weather } from "./rules";
2	import { inSeason } from "./season";
3	
4	export type CandidateItem = {
5	  id: string;
6	  category: string; // DB TitleCase: Tops/Bottoms/Outerwear/Shoes/Accessories/Fragrance
7	  colors: string[];
8	  formality: number | null;
9	  seasons: string[];
10	  material: string | null;
11	  /** Read together with `material` as warmth — see ./texture.ts. */
12	  texture: string | null;
13	  pattern: string | null;
14	};
15	
16	export type CandidateArgs = {
17	  band: [number, number];
18	  weather: Weather;
19	  season: string;
20	  excludeItemIds: string[];
21	  maxAccessories: number;
22	  /**
23	   * The user's rain-guard preference. Optional and defaulting ON, so every
24	   * existing caller and fixture keeps the protective behaviour it had before
25	   * the toggle existed.
26	   *
27	   * A bare boolean rather than the whole `Preferences` object: the generator
28	   * has no business importing a module that also carries display concerns like
29	   * the temperature unit.
30	   */
31	  rainGuard?: boolean;
32	};
33	
34	const CAP = 200;
35	
36	function gcd(x: number, y: number): number {
37	  return y === 0 ? x : gcd(y, x % y);
38	}
39	
40	/**
41	 * A step size that visits every index of a list of length `n` before repeating.
42	 *
43	 * `buildCandidates` walks shoes with a stride so their pairing does not move in
44	 * lockstep with bottoms. A FIXED stride of 2 was wrong: it shares a factor with
45	 * every even list length, so with one top — where the top index cannot supply
46	 * variation — a two-shoe closet reached only the first pair, and emitted the
47	 * same combo twice. Any stride coprime with `n` visits all of it, so pick the
48	 * smallest one above 1 and fall back to 1 for n ≤ 2.
49	 */
50	function decorrelatedStride(n: number): number {
51	  for (let s = 2; s < n; s++) if (gcd(s, n) === 1) return s;
52	  return 1;
53	}
54	
55	/** The required slots — a combo cannot exist without one of each. */
56	export const REQUIRED_CATEGORIES = ["Tops", "Bottoms", "Shoes"] as const;
57	export type RequiredCategory = (typeof REQUIRED_CATEGORIES)[number];
58	
59	/**
60	 * How far BELOW a band's floor an item may still qualify.
61	 *
62	 * Footwear gets a wider stretch than everything else because formality is a
63	 * poor fit for shoes: a clean minimal leather sneaker is genuinely valid
64	 * smart-casual work wear, so an f=2 sneaker should reach Work [3, 4.5]. The
65	 * stretch is deliberately one step, not unlimited — it lets sneakers into Work
66	 * but NOT into Evening [3.5, 5], and never lets an f=1 shoe into Work.
67	 */
68	function floorTolerance(category: string): number {
69	  return category === "Shoes" ? 1 : 0.5;
70	}
71	
72	function materialExcluded(material: string | null, excludeMaterials: string[]): boolean {
73	  if (!material) return false;
74	  const m = material.toLowerCase();
75	  // Substring, not equality: the tagger writes free text, so "merino wool" and
76	  // "suede leather" are real values that an exact match silently let through.
77	  return excludeMaterials.some((x) => m.includes(x));
78	}
79	
80	function isEligible(i: CandidateItem, a: CandidateArgs, excludeMaterials: string[]): boolean {
81	  const [lo, hi] = a.band;
