1	import { colorHarmonyScore, leanScore } from "./color";
2	import { seasonFit } from "./season";
3	import { warmthFit } from "./texture";
4	
5	export type ScoreItem = {
6	  category: string;
7	  colors: string[];
8	  formality: number | null;
9	  style_tags?: string[];
10	  seasons?: string[];
11	  /** "solid" | "striped" | "check" | "print" | "other". Null = no opinion. */
12	  pattern?: string | null;
13	  /** Fibre and construction. Together they carry warmth — see ./texture.ts. */
14	  material?: string | null;
15	  texture?: string | null;
16	};
17	export type Ctx = {
18	  aesthetic: string[];
19	  band: [number, number];
20	  /** Refine "Lean into" colour families. Empty = no preference. */
21	  lean?: string[];
22	  /**
23	   * Item ids from the set a regenerate is replacing. A SOFT preference applied
24	   * in `rankTopN`, never a filter: pieces sink in the ranking but are never
25	   * removed from the closet, so a small wardrobe still returns its one good
26	   * outfit instead of an empty screen.
27	   */
28	  recentlyShown?: string[];
29	  /** The current season ("Winter"). Absent = no season preference at all. */
30	  season?: string;
31	  /**
32	   * Today's temperature. Absent = no thermal reading, so the climate term falls
33	   * back to the season tag alone. Threaded from the forecast the generator
34	   * already fetches.
35	   */
36	  tempC?: number;
37	};
38	
39	/**
40	 * How much of the score the colour lean is allowed to claim when one is asked
41	 * for. High enough to reorder the top 20 decisively, low enough that a combo
42	 * missing the colour still beats an incoherent one that has it — the lean is a
43	 * preference, never an eliminator.
44	 */
45	const LEAN_WEIGHT = 0.3;
46	
47	/**
48	 * Climate — "does this suit the weather?" — is ONE term, not two.
49	 *
50	 * Season and warmth answer the same question with different evidence, so they
51	 * share a weight instead of competing for the score. Adding warmth as a third
52	 * independent preference would have pushed the total past 0.5 and squeezed
53	 * colour, formality and DNA below half whenever a Refine lean was also active;
54	 * merging keeps the budget bounded by construction and gives weather a single,
55	 * better-informed vote. Future weather work (wind, humidity) belongs inside
56	 * this term, not beside it.
57	 *
58	 * Slightly above the 0.2 season alone used to carry — the term now reads a real
59	 * temperature rather than only the month — and still low enough that an
60	 * off-season combo which actually works beats an in-season mess.
61	 */
62	const CLIMATE_WEIGHT = 0.28;
63	
64	/**
65	 * Within climate, how much of the vote the thermometer gets over the tag.
66	 *
67	 * Warmth leads because it reads today's temperature against this garment's
68	 * fibre and construction, where `seasons` is a coarse, user-editable proxy
69	 * that no closet fills in reliably. The tag keeps a real share because it
70	 * carries what fabric cannot say — a linen suit is Summer, a Christmas jumper
71	 * is December — and because it is the only climate signal left when a forecast
72	 * fails.
73	 */
74	const WARMTH_SHARE = 0.7;
75	
76	/** 1.0 = identical formality; falls off with spread. */
77	export function formalityCoherence(formalities: number[]): number {
78	  const f = formalities.filter((x) => typeof x === "number");
79	  if (f.length < 2) return 1;
80	  const spread = Math.max(...f) - Math.min(...f);
81	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
82	}
83	
84	/**
85	 * One patterned piece is a statement; two are an argument.
86	 *
87	 * Counts non-solid pieces: 0 or 1 is clean, each additional one costs. Floored
88	 * well above zero because a wardrobe of patterned shirts must still be
89	 * dressable — the same rule every other signal in this file follows.
90	 */
91	export function patternHarmony(patterns: (string | null | undefined)[]): number {
92	  const loud = patterns.filter((p) => p && p !== "solid").length;
93	  return loud <= 1 ? 1 : Math.max(0.3, 1 - (loud - 1) * 0.35);
94	}
95	
96	/**
97	 * How well the combo suits today, on whichever evidence exists.
98	 *
99	 * Returns null when there is neither a temperature nor a season, so the caller
100	 * can drop the term entirely rather than fold in a meaningless 0.5.
101	 */
102	function climateFit(items: ScoreItem[], ctx: Ctx): number | null {
103	  const warmth = ctx.tempC == null ? null : warmthFit(items, ctx.tempC);
104	  const season = ctx.season ? seasonFit(items, ctx.season) : null;
105	  if (warmth == null) return season;
106	  if (season == null) return warmth;
107	  return WARMTH_SHARE * warmth + (1 - WARMTH_SHARE) * season;
108	}
109	
110	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
111	  const colors = items.flatMap((i) => i.colors);
112	  const harmony = colorHarmonyScore(colors);
113	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
114	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
