import { colorHarmonyScore, leanScore } from "./color";
import { seasonFit } from "./season";
import { warmthFit } from "./texture";

export type ScoreItem = {
  category: string;
  colors: string[];
  formality: number | null;
  style_tags?: string[];
  seasons?: string[];
  /** "solid" | "striped" | "check" | "print" | "other". Null = no opinion. */
  pattern?: string | null;
  /** Fibre and construction. Together they carry warmth — see ./texture.ts. */
  material?: string | null;
  texture?: string | null;
};
export type Ctx = {
  aesthetic: string[];
  band: [number, number];
  /** Refine "Lean into" colour families. Empty = no preference. */
  lean?: string[];
  /**
   * Item ids from the set a regenerate is replacing. A SOFT preference applied
   * in `rankTopN`, never a filter: pieces sink in the ranking but are never
   * removed from the closet, so a small wardrobe still returns its one good
   * outfit instead of an empty screen.
   */
  recentlyShown?: string[];
  /** The current season ("Winter"). Absent = no season preference at all. */
  season?: string;
  /**
   * Today's temperature. Absent = no thermal reading, so the climate term falls
   * back to the season tag alone. Threaded from the forecast the generator
   * already fetches.
   */
  tempC?: number;
};

/**
 * How much of the score the colour lean is allowed to claim when one is asked
 * for. High enough to reorder the top 20 decisively, low enough that a combo
 * missing the colour still beats an incoherent one that has it — the lean is a
 * preference, never an eliminator.
 */
const LEAN_WEIGHT = 0.3;

/**
 * Climate — "does this suit the weather?" — is ONE term, not two.
 *
 * Season and warmth answer the same question with different evidence, so they
 * share a weight instead of competing for the score. Adding warmth as a third
 * independent preference would have pushed the total past 0.5 and squeezed
 * colour, formality and DNA below half whenever a Refine lean was also active;
 * merging keeps the budget bounded by construction and gives weather a single,
 * better-informed vote. Future weather work (wind, humidity) belongs inside
 * this term, not beside it.
 *
 * Slightly above the 0.2 season alone used to carry — the term now reads a real
 * temperature rather than only the month — and still low enough that an
 * off-season combo which actually works beats an in-season mess.
 */
const CLIMATE_WEIGHT = 0.28;

/**
 * Within climate, how much of the vote the thermometer gets over the tag.
 *
 * Warmth leads because it reads today's temperature against this garment's
 * fibre and construction, where `seasons` is a coarse, user-editable proxy
 * that no closet fills in reliably. The tag keeps a real share because it
 * carries what fabric cannot say — a linen suit is Summer, a Christmas jumper
 * is December — and because it is the only climate signal left when a forecast
 * fails.
 */
const WARMTH_SHARE = 0.7;

/** 1.0 = identical formality; falls off with spread. */
export function formalityCoherence(formalities: number[]): number {
  const f = formalities.filter((x) => typeof x === "number");
  if (f.length < 2) return 1;
  const spread = Math.max(...f) - Math.min(...f);
  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
}

/**
 * One patterned piece is a statement; two are an argument.
 *
 * Counts non-solid pieces: 0 or 1 is clean, each additional one costs. Floored
 * well above zero because a wardrobe of patterned shirts must still be
 * dressable — the same rule every other signal in this file follows.
 */
export function patternHarmony(patterns: (string | null | undefined)[]): number {
  const loud = patterns.filter((p) => p && p !== "solid").length;
  return loud <= 1 ? 1 : Math.max(0.3, 1 - (loud - 1) * 0.35);
}

/**
 * How well the combo suits today, on whichever evidence exists.
 *
 * Returns null when there is neither a temperature nor a season, so the caller
 * can drop the term entirely rather than fold in a meaningless 0.5.
 */
function climateFit(items: ScoreItem[], ctx: Ctx): number | null {
  const warmth = ctx.tempC == null ? null : warmthFit(items, ctx.tempC);
  const season = ctx.season ? seasonFit(items, ctx.season) : null;
  if (warmth == null) return season;
  if (season == null) return warmth;
  return WARMTH_SHARE * warmth + (1 - WARMTH_SHARE) * season;
}

export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
  const colors = items.flatMap((i) => i.colors);
  const harmony = colorHarmonyScore(colors);
  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
  const dna = items.length ? dnaHits / items.length : 0;
  const pattern = patternHarmony(items.map((i) => i.pattern));
  const base = 0.4 * harmony + 0.3 * coherence + 0.15 * dna + 0.15 * pattern;

  // Each preference claims its weight only when it applies, so with neither one
  // set the score is byte-identical to what it was before either landed.
  const climate = climateFit(items, ctx);
  const wl = ctx.lean?.length ? LEAN_WEIGHT : 0;
  const wc = climate == null ? 0 : CLIMATE_WEIGHT;
  return Math.min(
    1,
    base * (1 - wl - wc) + wl * leanScore(colors, ctx.lean ?? []) + wc * (climate ?? 0),
  );
}

/**
 * Warmth — the signal that decides whether a garment suits today's temperature.
 *
 * The tagger has always written `pattern`, and `texture` arrived with
 * `item-data-completeness`; the generator read neither, so a chunky knit and a
 * fine knit were interchangeable in February. Until now the only thermal read
 * in the product was `seasonFit`, which knows the MONTH, not the weather, and
 * `HOT_MATERIALS`, a keyword list. This module is where warmth becomes real:
 * actual temperature against actual cloth.
 *
 * It is a PREFERENCE. It shifts ranking and can never eliminate a candidate —
 * the same model as outerwear, the colour lean and season, each of which was a
 * hard filter that silently emptied a wardrobe.
 */

/**
 * How the fabric is BUILT.
 *
 * Exported for the vocabulary-drift guard in `__tests__/texture.test.ts`: a
 * value the tagger may emit that is missing here scores 0.5 — indistinguishable
 * from the mid-warmth fabrics genuinely worth 0.5 — so the test checks
 * membership, not the number.
 */
export const TEXTURE_WARMTH: Record<string, number> = {
  "Open knit": 0.15,
  Seersucker: 0.2,
  "Fine knit": 0.25,
  Flat: 0.4,
  Twill: 0.45,
  Herringbone: 0.55,
  Waffle: 0.6,
  Ribbed: 0.6,
  Terry: 0.65,
  Brushed: 0.7,
  "Cable knit": 0.8,
  Quilted: 0.85,
  Pile: 0.85,
  "Chunky knit": 0.9,
  "Fleece-back": 0.9,
};

/**
 * What the fabric IS. Carries the warmth a weave cannot express — tweed is warm
 * however it is woven, linen is cool however it is knitted.
 *
 * `Stainless steel`, `Gold`, `Silver`, `Rubber` and `Other` are deliberately
 * ABSENT: hardware has no thermal opinion, and a value here would make a watch
 * argue about the weather. They fall through to neutral, which is the truth.
 */
export const MATERIAL_WARMTH: Record<string, number> = {
  Linen: 0.15,
  Silk: 0.3,
  Viscose: 0.35,
  Lyocell: 0.35,
  Modal: 0.35,
  Cotton: 0.45,
  Denim: 0.5,
  Canvas: 0.5,
  Nylon: 0.5,
  Polyester: 0.5,
  Leather: 0.55,
  "Faux leather": 0.55,
  Acrylic: 0.6,
  "Merino wool": 0.6,
  // Nap traps air, and it is a cold-season shoe. A small margin over smooth
  // leather on purpose — both are shoes, which barely move the reading anyway.
  Suede: 0.6,
  Wool: 0.65,
  Corduroy: 0.7,
  Cashmere: 0.75,
  Tweed: 0.85,
  Fleece: 0.9,
  Down: 0.95,
  Shearling: 0.95,
};

/**
 * Insulation: warm no matter how it is built, so construction cannot argue it
 * down. This is the set `HOT_MATERIALS` in lib/generator/rules.ts keeps as a
 * hard exclusion; here it also pins the floor of the soft signal.
 */
const INSULATION = new Set(["Fleece", "Down", "Shearling"]);

/** Texture leads, material grounds it. */
const TEXTURE_SHARE = 0.65;

/**
 * 0 = coolest, 1 = warmest, 0.5 = no opinion (untagged or unknown).
 *
 * Reads BOTH dimensions on purpose. Texture alone misses tweed, whose warmth is
 * in the cloth and whose weave a linen shirt also uses. Material alone misses
 * the merino case — a chunky merino knit and a fine merino tee share a fibre and
 * are a season apart. Texture carries the larger share because construction is
 * the stronger signal where both are known, but material sets the floor.
 */
export function itemWarmth(material: string | null, texture: string | null): number {
  const m = material ? MATERIAL_WARMTH[material] : undefined;
  const t = texture ? TEXTURE_WARMTH[texture] : undefined;
  if (m === undefined && t === undefined) return 0.5; // no opinion, never a penalty
  if (t === undefined) return m!;
  if (m === undefined) return t;
  const blended = TEXTURE_SHARE * t + (1 - TEXTURE_SHARE) * m;
  // A fine-knit fleece is still a fleece.
  return material && INSULATION.has(material) ? Math.max(blended, m) : blended;
}

/**
 * How much each slot actually decides whether you are warm.
 *
 * A flat average lets a steel watch and a pair of shoes pull every outfit
 * toward neutral — exactly when the signal should be loudest. Matched by
 * prefix on the lowercased category so DB TitleCase plurals (`Tops`) and the
 * singular fixtures used in scoring tests (`top`) both land.
 */
const CATEGORY_WEIGHT: [string, number][] = [
  ["outerwear", 1.5],
  ["top", 1.2],
  ["bottom", 1],
  ["shoe", 0.6],
  ["accessor", 0.2],
  ["fragrance", 0],
];

function categoryWeight(category?: string | null): number {
  if (!category) return 1; // uncategorised still counts; never silently zeroed
  const c = category.toLowerCase();
  return CATEGORY_WEIGHT.find(([prefix]) => c.startsWith(prefix))?.[1] ?? 1;
}

/**
 * How well a combo's warmth suits the temperature. 0..1, 0.5 = no opinion.
 *
 * `want` maps 25°+ → 0 (want the lightest) and 0° → 1 (want the warmest), and
 * passes through 0.5 at 12.5°.
 *
 * `confidence` is the part that matters and the part a plain `1 - |want - have|`
 * cannot express: that formula's gap between two garments is CONSTANT once
 * `want` sits outside them, so 18° would discriminate exactly as hard as 0°.
 * Fading the whole term toward neutral as the temperature approaches 12.5°
 * gives the intended shape — hardest at the extremes, silent in the middle,
 * where a ribbed knit and a flat shirt are both simply correct and colour,
 * formality and DNA should decide instead.
 */
export function warmthFit(
  items: { category?: string | null; material?: string | null; texture?: string | null }[],
  tempC: number,
): number {
  if (!items.length) return 0.5;
  const want = Math.min(1, Math.max(0, (25 - tempC) / 25));

  let weighted = 0;
  let total = 0;
  for (const i of items) {
    const w = categoryWeight(i.category);
    weighted += w * itemWarmth(i.material ?? null, i.texture ?? null);
    total += w;
  }
  if (total === 0) return 0.5; // nothing in the combo has a thermal say
  const have = weighted / total;

  const confidence = Math.abs(want - 0.5) * 2;
  return 0.5 + confidence * (1 - Math.abs(want - have) - 0.5);
}
